import shutil
import datetime
import openpyxl
from openpyxl.styles import PatternFill

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["Data"]
vws = vals["Data"]

def to_date(v):
    if v is None:
        return None
    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%m/%d/%y", "%d-%b-%Y"):
            try:
                return datetime.datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

def add_months(d, months):
    months = int(months)
    total = d.year * 12 + (d.month - 1) + months
    y, m = divmod(total, 12)
    m += 1
    return datetime.date(y, m, 1)

def to_num(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

# fallback frequency map from lookup table if J missing
freq_map = {}
for r in range(6, 9):
    key = vws[f"I{r}"].value
    val = to_num(vws[f"J{r}"].value)
    if key is not None and val is not None:
        freq_map[str(key).strip()] = int(val)

old_cols = ["Q","R","S","T","U","V","W","X","Y","Z","AA","AB"]
new_cols = ["AD","AE","AF","AG","AH","AI","AJ","AK","AL","AM","AN","AO"]
inc_cols = ["M","N","O","P"]

new_dates = [to_date(vws[f"{c}9"].value) for c in new_cols]
if any(d is None for d in new_dates):
    q9 = to_date(vws["Q9"].value)
    if q9 is not None:
        new_dates = [add_months(q9, 12 + i) for i in range(12)]

no_fill = PatternFill(fill_type=None)
count = 0
for r in range(14, 43):
    eff = to_date(vws[f"L{r}"].value)
    freq = to_num(vws[f"J{r}"].value)
    if freq is None:
        i_val = vws[f"I{r}"].value
        if i_val is not None:
            freq = to_num(freq_map.get(str(i_val).strip()))
    incs = [to_num(vws[f"{c}{r}"].value) for c in inc_cols]
    for idx, (nc, oc) in enumerate(zip(new_cols, old_cols)):
        cell = ws[f"{nc}{r}"]
        cell.fill = no_fill
        d = new_dates[idx]
        base = to_num(vws[f"{oc}{r}"].value)
        result = None
        if eff is not None and d is not None and d >= eff and freq is not None and freq > 0 and base is not None:
            factor = 1.0
            for i, inc in enumerate(incs):
                if inc is None:
                    break
                wave = add_months(eff, i * int(freq))
                if d >= wave:
                    factor *= (1.0 + inc)
            result = base * factor
        if result is None:
            cell.value = None
        else:
            result = round(result, 2)
            if result == 0:
                result = 0.0
            cell.value = result
            count += 1
    if r in (14,17,25,40):
        print(r, [ws[f"{c}{r}"].value for c in new_cols[:4]])

wb.save(OUT)
print("done", count)
